parameters.jsCode:
const action = $('Webhook').first().json.body.action || 'create';  // Default a 'create' si no se envía
const type = $('Webhook').first().json.body.type;

// Si action no es 'retry', asumir que es creación (compatible hacia atrás)
if (action !== 'retry') {
  if (type === 'token') {
    const preference = $('Create Preference (Token)').first().json;
    const transaction = $('Insert Token Transaction').first().json;
    return [{
      json: {
        success: true,
        action: 'create',
        type: 'token',
        checkoutUrl: preference.init_point,
        preferenceId: preference.id,
        init_point: preference.init_point,
        sandbox_init_point: preference.init_point,
        transactionId: transaction.id
      }
    }];
  } else if (type === 'service') {
    const preference = $('Create Preference (Service)').first().json;
    const order = $('Get Service Order (Create)').first().json;

    return [{
      json: {
        success: true,
        action: 'create',
        type: 'service',
        checkoutUrl: preference.init_point,
        preferenceId: preference.id,
        init_point: preference.init_point,
        sandbox_init_point: preference.init_point,
        serviceOrderId: order.id
      }
    }];
  }
} else if (action === 'retry') {
  const isToken = $('Webhook').first().json.body.transactionId !== undefined;

  if (isToken) {
    const preference = $('Get Token Preference').first().json;
    const transaction = $('Get Token Transaction (Retry)').first().json;

    return [{
      json: {
        success: true,
        action: 'retry',
        type: 'token',
        checkoutUrl: preference.init_point,
        preferenceId: preference.id,
        init_point: preference.init_point,
        sandbox_init_point: preference.init_point,
        transactionId: transaction.id
      }
    }];
  } else {
    const preference = $('Get Service Preference').first().json;
    const order = $('Get Service Order (Retry)').first().json;

    return [{
      json: {
        success: true,
        action: 'retry',
        type: 'service',
        checkoutUrl: preference.init_point,
        preferenceId: preference.id,
        init_point: preference.init_point,
        sandbox_init_point: preference.init_point,
        serviceOrderId: order.id
      }
    }];
  }
}

throw new Error('Invalid action or type');

